[
  {
    "sys_fairness_reciprocity": "We did identical work, so anything else would feel crooked",
    "ce_mental_state_attribution": "Is it a test of whether I'm greedy?",
    "ce_mentalizing_difficulty": "I just can't read what's going on in their head",
    "pd_personal_consequence_anxiety": "makes me a bit uneasy that they might file me away",
    "pda_self_consequence_regret": "I'd really regret losing their good opinion"
  },
  {
    "sys_fairness_reciprocity": "Equal hours, equal effort, equal thanks",
    "ce_mental_state_attribution": "Would they be grateful, or quietly annoyed that I had any say at all?",
    "ce_mentalizing_difficulty": "I can't predict that about them",
    "pd_personal_consequence_anxiety": "makes my stomach tighten"
  },
  {
    "ce_mental_state_attribution": "Are they being respectful, or passing off an awkward call?",
    "ce_mentalizing_difficulty": "I just can't read them",
    "pd_personal_consequence_anxiety": "I get nervous picturing myself as the gatekeeper",
    "pda_self_consequence_regret": "I'd hate to end up regretting a reputation"
  },
  {
    "ce_mental_state_attribution": "what they really expect me to say",
    "ce_mentalizing_difficulty": "I can't tell from the way they've framed it",
    "pd_personal_consequence_anxiety": "I'd be anxious that any pause on my end reads as petty",
    "pda_self_consequence_regret": "If I lost their trust over a moment of hesitation, I'd kick myself"
  },
  {
    "sys_fairness_reciprocity": "like taking credit for shared work",
    "ce_mental_state_attribution": "Do they think we were both paid automatically?",
    "ce_mentalizing_difficulty": "I honestly can't read their expectations",
    "pd_personal_consequence_anxiety": "scared that if they found out, they'd never quite trust me again",
    "pda_self_consequence_regret": "That's a loss I'd regret badly"
  },
  {
    "sys_fairness_reciprocity": "We split the work down the middle",
    "sys_rule_justification": "the payment was theirs by right",
    "ce_mental_state_attribution": "having them feel indebted",
    "ce_mentalizing_difficulty": "I can't tell what the organizer hopes to get",
    "pd_personal_consequence_anxiety": "I'm uneasy about owing anyone a thank-you I don't deserve",
    "pda_self_consequence_regret": "I'd regret getting tangled up as some kind of middleman"
  },
  {
    "ce_mental_state_attribution": "Maybe they respect my opinion, maybe they want a fall guy",
    "ce_mentalizing_difficulty": "I genuinely can't decode that",
    "pd_personal_consequence_anxiety": "Being blamed later honestly worries me",
    "pda_self_consequence_regret": "I'd regret that for my standing in the community",
    "sys_consequence_reasoning": "If this turned into a story where I'm the one who decided"
  },
  {
    "sys_fairness_reciprocity": "Apply the same standard you used for me",
    "ce_mental_state_attribution": "praise, a verdict, loyalty?",
    "ce_mentalizing_difficulty": "I can't tell what the organizer truly wants from me",
    "pd_personal_consequence_anxiety": "I get jittery imagining my coworker hearing I had the final word",
    "pda_self_consequence_regret": "I'd regret losing their easy trust in me"
  },
  {
    "sys_fairness_reciprocity": "Equal work gets equal thanks",
    "ce_mental_state_attribution": "whether they'd feel singled out",
    "ce_mentalizing_difficulty": "they're just a tough person to figure out",
    "pd_personal_consequence_anxiety": "I worry they might think I was dangling something"
  },
  {
    "sys_fairness_reciprocity": "Anything less would feel unfair to me given we did the same work",
    "ce_mental_state_attribution": "Do they doubt my coworker's effort, or doubt me?",
    "ce_mentalizing_difficulty": "I can't read their intentions, even with the facts clear",
    "pd_personal_consequence_anxiety": "It makes me nervous that my answer could shape how they see me",
    "pda_self_consequence_regret": "If I came across as small-minded, I'd regret that"
  }
]
